sql.where:
del_flag = '0'

    AND code like concat('%', #{code}, '%')


    AND name like concat('%', #{name}, '%')


    AND runtime = #{runtime}


    AND enabled = #{enabled}


    AND builtin = #{builtin}

mapper.select:
select count(1) from agent_config
where del_flag = '0' and name = #{name}

    and id != #{excludeId}
